    function details(id){const t=p.data.techniques.find(t=>t.id===id),s=state(id),modal=document.getElementById('details');modal.innerHTML=`<button class="close" aria-label="Close details">×</button><h2>${esc(t.name)}</h2><p>${t.id} · ${esc(t.platforms.join(', '))}</p>${s.entries.length?s.entries.map(e=>`<div class="evidence"><b>${esc(e.layer)}</b>${chips([e])}${e.name?'<p class="mapping-scenario">'+esc(e.name)+'</p>':''}${e.type==='detection'?`<p class="detection-positive">Detection mapped in this layer${e.detections?.length?' · Rule names: '+e.detections.map(esc).join(', '):''}</p>`:''}${e.riskAcceptance?'<p class="risk-acceptance-note"><b>Risk accepted · '+esc(e.riskAcceptance.date)+'</b><br>'+esc(e.riskAcceptance.notes||'No acceptance notes recorded.')+'</p>':''}${e.type==='opportunity'?'<p class="logging-label">'+esc(Strata.loggingSummary([e]).label)+'</p>':''}<div class="notes">${esc(e.notes||'No notes provided.')}</div><small>${e.type==='intel'?'Mapping completed on':'Reviewed on'}: ${esc(e.date||'Not recorded')}</small></div>`).join(''):'<p>No evidence in the visible layers. Coverage is unknown.</p>'}`;modal.querySelector('button').onclick=()=>modal.close();modal.showModal();}render();
